  { text: "\u4F60\u66F4\u76F8\u4FE1\u2014\u2014", a: "\u4EB2\u773C\u770B\u5230\u3001\u4EB2\u624B\u505A\u8FC7\u7684\u4E8B", b: "\u76F4\u89C9\u548C\u300C\u611F\u89C9\u4F1A\u662F\u8FD9\u6837\u300D", dim: "SN", aPole: "S" },
  { text: "\u542C\u8BFE\u7684\u65F6\u5019\uFF0C\u4F60\u66F4\u5BB9\u6613\u2014\u2014", a: "\u8054\u60F3\u5230\u522B\u7684\u6709\u8DA3\u7684\u4E8B\uFF0C\u5076\u5C14\u8D70\u795E", b: "\u8DDF\u7740\u8001\u5E08\u7684\u677F\u4E66\u4E00\u6B65\u4E00\u6B65\u8BB0", dim: "SN", aPole: "N" },
  { text: "\u7ED9\u522B\u4EBA\u8BB2\u4E00\u4EF6\u4E8B\u65F6\uFF0C\u4F60\u503E\u5411\u4E8E\u2014\u2014", a: "\u6309\u987A\u5E8F\u628A\u6765\u9F99\u53BB\u8109\u8BB2\u6E05\u695A", b: "\u5148\u8BF4\u91CD\u70B9\u548C\u81EA\u5DF1\u7684\u60F3\u6CD5", dim: "SN", aPole: "S" }
