    careerFields: ["\u521B\u4E1A\u4E0E\u65B0\u4EA7\u54C1\u5F00\u53D1", "\u4EA7\u54C1\u7B56\u5212\u4E0E\u8BBE\u8BA1", "\u4F20\u5A92\u4E0E\u5185\u5BB9\u521B\u4F5C", "\u79D1\u6280\u521B\u65B0"]
