    workStyle: "\u66F4\u613F\u610F\u4ECE\u4E8B\u76F4\u63A5\u5E2E\u52A9\u4ED6\u4EBA\u7684\u5DE5\u4F5C\uFF1A\u533B\u751F\u3001\u6559\u5E08\u3001\u793E\u5DE5\u3001\u5FC3\u7406\u54A8\u8BE2\u5E08\u3001\u516C\u76CA\u4ECE\u4E1A\u8005\u2014\u2014\u7528\u81EA\u5DF1\u7684\u80FD\u529B\u56DE\u5E94\u522B\u4EBA\u7684\u9700\u8981\u3002",
    recognition: "\u5E0C\u671B\u88AB\u8BA4\u53EF\u7684\u662F\u5E26\u6765\u7684\u6539\u53D8\u2014\u2014\u300C\u56E0\u4E3A\u6709\u4ED6/\u5979\uFF0C\u522B\u4EBA\u66F4\u597D\u4E86\u300D\u3002",
