    careerFields: ["\u6587\u5316\u4E0E\u4F11\u95F2\u4EA7\u4E1A", "\u73AF\u5883\u4E0E\u8BBE\u8BA1", "\u516C\u5171\u4E8B\u4E1A", "\u5F39\u6027\u5DE5\u4F5C\u5236\u7684\u4E13\u4E1A\u5C97\u4F4D"]
