function buildHollandReport(result) {
  const dims = HOLLAND_ORDER.map((key) => {
    const c = HOLLAND_CONTENT[key];
    return {
      key,
      label: HOLLAND_LABEL[key],
      trait: c.trait,
      score: result.dims[key],
      studyImpact: c.studyImpact,
      careers: c.careers,
      majors: c.majors,
      isTop: result.top3.includes(key)
    };
  });
  const top3 = result.top3.map((key) => ({
    key,
    label: HOLLAND_LABEL[key],
    score: result.dims[key],
    focus: TOP_FOCUS[key]
  }));
  const relationNote = "\u970D\u5170\u5FB7\u516D\u578B\u5728\u516D\u8FB9\u5F62\u6A21\u578B\u4E2D\u5B58\u5728\u300C\u76F8\u90BB\u3001\u76F8\u9694\u3001\u76F8\u5BF9\u300D\u4E09\u79CD\u5173\u7CFB\uFF1A\u76F8\u90BB\u7684\u4E24\u578B\uFF08\u5982 S \u4E0E E\u3001I \u4E0E A\uFF09\u76F8\u4F3C\u5EA6\u9AD8\uFF0C\u5E38\u4E00\u8D77\u51FA\u73B0\uFF1B\u76F8\u9694\u4E3A\u4E2D\u6027\uFF1B\u76F8\u5BF9\u7684\u4E24\u578B\uFF08\u5982 R \u4E0E S\u3001I \u4E0E E\u3001A \u4E0E C\uFF09\u5DEE\u5F02\u6700\u5927\uFF0C\u82E5\u540C\u65F6\u5F97\u5206\u9AD8\uFF0C\u8BF4\u660E\u4F60\u5174\u8DA3\u9762\u5F88\u5BBD\u3002\u4F60\u7684\u4EE3\u7801\u300C" + result.code + "\u300D\u8D8A\u9760\u524D\u7684\u5B57\u6BCD\uFF0C\u4EE3\u8868\u4E0E\u4F60\u8D8A\u5951\u5408\u7684\u65B9\u5411\u3002";
  return { code: result.code, keywords: result.keywords, relationNote, dims, top3 };
}

